src='''from collections import deque
def transform(grid):
    a=[row[:] for row in grid]; h=len(a); w=len(a[0]); bg=a[0][0]
    seen=set(); q=deque()
    for r in range(h):
        for c in (0,w-1):
            if a[r][c]==bg and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if a[r][c]==bg and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and a[nr][nc]==bg:
                seen.add((nr,nc)); q.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if a[r][c]==bg and (r,c) not in seen: a[r][c]=4
    return a
'''
